import type { CSSProperties, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface IconMorphPaths {
  from: string[];
  to: string[];
}

export interface IconMorphProps {
  state: boolean;
  from: ReactNode;
  to: ReactNode;
  paths?: IconMorphPaths;
  size?: number;
  strokeWidth?: number;
  className?: string;
  style?: CSSProperties;
}

const pathCommands = (path: string) => path.match(/[a-z]/gi)?.join("") ?? "";
const pathValues = (path: string) =>
  path.match(/-?(?:\d*\.)?\d+(?:e[-+]?\d+)?/gi)?.length ?? 0;

function pathsCanMorph(paths?: IconMorphPaths) {
  if (!paths || paths.from.length === 0 || paths.from.length !== paths.to.length) {
    return false;
  }

  return paths.from.every(
    (path, index) =>
      pathCommands(path) === pathCommands(paths.to[index] ?? "") &&
      pathValues(path) === pathValues(paths.to[index] ?? ""),
  );
}

export const iconMorphPresets = {
  menuClose: {
    from: ["M4 7L20 7", "M4 12L20 12", "M4 17L20 17"],
    to: ["M6 6L18 18", "M12 12L12 12", "M18 6L6 18"],
  },
  plusCheck: {
    from: ["M12 5L12 19", "M5 12L19 12"],
    to: ["M5 13L10 18", "M10 18L19 7"],
  },
  playPause: {
    from: ["M7 5L12 8L12 16L7 19Z", "M12 8L19 12L12 16L12 8Z"],
    to: ["M7 5L11 5L11 19L7 19Z", "M14 5L18 5L18 19L14 19Z"],
  },
  chevron: {
    from: ["M6 9L12 15L18 9"],
    to: ["M9 6L15 12L9 18"],
  },
} satisfies Record<string, IconMorphPaths>;

export function IconMorph({
  state,
  from,
  to,
  paths,
  size = 24,
  strokeWidth = 1.75,
  className,
  style,
}: IconMorphProps) {
  const reduceMotion = useReducedMotion() ?? false;
  const canMorph = pathsCanMorph(paths);
  const rootStyle = {
    ...style,
    "--icon-morph-size": `${size}px`,
  } as CSSProperties;

  if (canMorph && paths) {
    return (
      <motion.svg
        className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
        style={rootStyle}
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        focusable="false"
      >
        {paths.from.map((path, index) => (
          <motion.path
            key={index}
            initial={false}
            animate={{ d: state ? paths.to[index] : path }}
            transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
          />
        ))}
      </motion.svg>
    );
  }

  const hidden = {
    opacity: 0,
    scale: reduceMotion ? 1 : 0.62,
  };
  const visible = { opacity: 1, scale: 1 };
  const transition = reduceMotion
    ? { duration: 0 }
    : {
        scale: motionTokens.spring.smooth,
        opacity: {
          duration: motionTokens.duration.fast,
          ease: motionTokens.ease.standard,
        },
      };

  return (
    <span
      className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
      style={rootStyle}
      aria-hidden="true"
    >
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? hidden : visible}
        transition={transition}
      >
        {from}
      </motion.span>
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? visible : hidden}
        transition={transition}
      >
        {to}
      </motion.span>
    </span>
  );
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  type HTMLMotionProps,
} from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

type SpanProps = Omit<HTMLMotionProps<"span">, "children">;

export interface MorphingTextProps extends SpanProps {
  value: string;
}

interface TextDifference {
  prefix: string;
  previous: string;
  current: string;
  suffix: string;
}

function compareText(previous: string, current: string): TextDifference {
  const previousCharacters = Array.from(previous);
  const currentCharacters = Array.from(current);
  const sharedLength = Math.min(previousCharacters.length, currentCharacters.length);
  let prefixLength = 0;

  while (
    prefixLength < sharedLength &&
    previousCharacters[prefixLength] === currentCharacters[prefixLength]
  ) {
    prefixLength += 1;
  }

  let previousEnd = previousCharacters.length;
  let currentEnd = currentCharacters.length;

  while (
    previousEnd > prefixLength &&
    currentEnd > prefixLength &&
    previousCharacters[previousEnd - 1] === currentCharacters[currentEnd - 1]
  ) {
    previousEnd -= 1;
    currentEnd -= 1;
  }

  return {
    prefix: currentCharacters.slice(0, prefixLength).join(""),
    previous: previousCharacters.slice(prefixLength, previousEnd).join(""),
    current: currentCharacters.slice(prefixLength, currentEnd).join(""),
    suffix: currentCharacters.slice(currentEnd).join(""),
  };
}

export function MorphingText({
  value,
  className,
  style,
  ...props
}: MorphingTextProps) {
  const [change, setChange] = useState({ previous: value, current: value });
  const measureRef = useRef<HTMLSpanElement>(null);
  const firstMeasurement = useRef(true);
  const reduceMotion = useReducedMotion() ?? false;
  const width = useMotionValue(0);

  if (change.current !== value) {
    setChange({ previous: change.current, current: value });
  }

  const difference = compareText(change.previous, change.current);
  const changedText = difference.current;
  const hasChangedText = Boolean(difference.previous || changedText);

  useLayoutEffect(() => {
    const measure = measureRef.current;
    if (!measure) return;
    let stopAnimation = () => {};

    const resize = () => {
      const nextWidth = measure.getBoundingClientRect().width;
      stopAnimation();

      if (firstMeasurement.current || reduceMotion) {
        firstMeasurement.current = false;
        width.jump(nextWidth);
        return;
      }

      const controls = animate(width, nextWidth, motionTokens.spring.smooth);
      stopAnimation = () => controls.stop();
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(measure);
    return () => {
      stopAnimation();
      observer.disconnect();
    };
  }, [changedText, reduceMotion, width]);

  return (
    <motion.span
      {...props}
      className={["relative inline-block whitespace-nowrap", className].filter(Boolean).join(" ")}
      style={style}
      aria-live="polite"
    >
      <span className="absolute size-px overflow-hidden [clip:rect(0,0,0,0)] [clip-path:inset(50%)] whitespace-nowrap">{value}</span>
      <span className="inline-flex items-baseline whitespace-nowrap" aria-hidden="true">
        <span className="whitespace-pre">{difference.prefix}</span>
        <motion.span className="relative inline-grid min-w-0 overflow-hidden text-start" style={{ width }}>
          {hasChangedText ? (
            <motion.span
              key={change.current}
              className="absolute top-0 left-0 flex w-max flex-col [line-height:inherit] will-change-transform"
              initial={{
                transform: reduceMotion ? "translateY(-50%)" : "translateY(0%)",
              }}
              animate={{ transform: "translateY(-50%)" }}
              transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
            >
              <span className="block h-[1lh] whitespace-pre">
                {difference.previous || "\u00a0"}
              </span>
              <span className="block h-[1lh] whitespace-pre">{changedText || "\u00a0"}</span>
            </motion.span>
          ) : null}
          <span className="col-[1] row-[1] invisible inline-block justify-self-start whitespace-pre pointer-events-none">{changedText || "\u00a0"}</span>
          <span ref={measureRef} className="absolute invisible w-max whitespace-pre pointer-events-none">
            {changedText}
          </span>
        </motion.span>
        <span className="whitespace-pre">{difference.suffix}</span>
      </span>
    </motion.span>
  );
}
